// A push button between `pin` and GND, read with the internal pull-up (pressed reads LOW).
//
// `pressed()` is true once per press: on the pass where the reading has been LOW for kDebounceMs after having been
// stably HIGH. Releasing reports nothing. A button already held at begin() is not a press.
class Button {
 public:
  static constexpr uint32_t kDebounceMs = 50;

  constexpr explicit Button(uint8_t pin) : pin_(pin), down_(false), reading_(false), changed_(0) {}

  void begin() {
    pinMode(pin_, INPUT_PULLUP);
    begin(millis(), digitalRead(pin_) == LOW);
  }

  // Starts with `down` as the debounced state, so a button held at power-up does not count as a press.
  void begin(uint32_t now, bool down) {
    down_ = down;
    reading_ = down;
    changed_ = now;
  }

  bool pressed() { return pressed(millis()); }
  bool pressed(uint32_t now) { return update(now, digitalRead(pin_) == LOW); }

  // One debounce step with the raw reading `down` (true = LOW) at time `now`.
  bool update(uint32_t now, bool down) {
    if (down != reading_) {
      reading_ = down;
      changed_ = now;
      return false;
    }
    if (down != down_ && now - changed_ >= kDebounceMs) {
      down_ = down;
      return down;
    }
    return false;
  }

 private:
  uint8_t pin_;
  bool down_;         // Debounced state.
  bool reading_;      // Last raw reading.
  uint32_t changed_;  // When the raw reading last changed.
};

// A drift-free periodic timer: due() is true one interval after begin(), then every interval.
//
// Each tick is scheduled one interval after the previous scheduled tick (`last_ += interval_`), not after the moment
// it was noticed. due() reports at most one tick per call, so ticks missed while callbacks ran are reported on the
// following calls, one per call, until the timer has caught up.
class Every {
 public:
  constexpr explicit Every(uint32_t interval) : interval_(interval), last_(0) {}

  void begin() { begin(millis()); }
  void begin(uint32_t now) { last_ = now; }

  bool due() { return due(millis()); }
  bool due(uint32_t now) {
    if (now - last_ < interval_) return false;
    last_ += interval_;
    return true;
  }

 private:
  uint32_t interval_;
  uint32_t last_;
};

// A value with a "changed" mark (docs/SUBSET.md "Signals"). T is int32_t, float, bool, uint8_t, uint16_t or int16_t.
//
// set() stores a value that differs from the current one (`!=`, so NaN always differs and -0.0 equals 0.0) and marks
// the signal changed; an equal value changes nothing. take() reports the mark and clears it. A signal starts
// changed, so its initial value is delivered at the end of setup(). Delivery itself is generated code
// (unodar_deliver()): set() never calls anything.
